// The D&D 5.5e (SRD 5.2.1) search index (lib/srdIndex.ts has the entry
// shape), generated by scripts/build-dnd-srd-index.ts from the JSON in
// public/5_5_SRD/. Re-run `npm run build:dnd-index` after changing it.

import type { SrdEntry } from "./srdIndex";

// In display order.
export const DND_SRD_CATEGORIES = [
    "Monster", "Spell", "Magic Item", "Equipment", "Class", "Class Feature",
    "Feat", "Species", "Background", "Rule",
] as const;

export type DndSrdCategory = typeof DND_SRD_CATEGORIES[number];
export type DndSrdEntry = SrdEntry<DndSrdCategory>;

export const DND_SRD_INDEX_PATH = "/5_5_SRD/search-index.json";
